import com.company.generated.units.u66bf2c108225.ErrorReply;
import com.company.generated.units.u66bf2c108225.StandardErrorRSFmtMapper;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;

@ControllerAdvice
public class GlobalExceptionHandler {

    private final StandardErrorRSFmtMapper errorMapper = new StandardErrorRSFmtMapper();

    @ExceptionHandler(Exception.class)
    public ResponseEntity<String> handleException(Exception ex) {
        try {
            ErrorReply reply = new ErrorReply("99", "990", ex.getMessage() != null ? ex.getMessage() : "Unexpected technical error", "REQ-ERR-001");
            String xml = errorMapper.format(reply);
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                    .contentType(MediaType.APPLICATION_XML)
                    .body(xml);
        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                    .contentType(MediaType.APPLICATION_XML)
                    .body("<ErrorReply><ErrorCategory>99</ErrorCategory><ErrorNumber>990</ErrorNumber><ErrorDescription>Critical System Error</ErrorDescription><RequestId>REQ-ERR-001</RequestId></ErrorReply>");
        }
    }
}
